using System.Text;
using Stride.Core.Diagnostics;
using Stride.Core.IO;
using Stride.Core.Storage;
using Stride.Shaders.Compilers;
using Stride.Shaders.Compilers.SDSL;
using Stride.Shaders.Parsing.Upgrade;

namespace Stride.Shaders.Parsers.Tests;

/// <summary>
/// Sources loaded at run time, outside the asset pipeline (files a tool reads from the disk, sources generated by code), are
/// upgraded when they are written for an older Stride version (<see cref="ShaderUpgrader.UpgradeSource"/>), with warning SDSL0216.
/// </summary>
public class ShaderSourceUpgradeTests : IDisposable
{
    // The base of the nodes a tool composes (like VL's ComputeVoid): not an engine class, and nothing in it says it is composed
    const string NodeBase = """
        shader {0}
        {
            void Compute()
            {
            }
        };
        """;

    // Written like a 4.4 node generated at run time: `stage`, and ComputeShaderBase inherited to read the thread streams in a composition
    const string OldComputeNode = """
        shader {0} : {1}, ComputeShaderBase
        {
            stage stream float Weight;
            RWBuffer<float> Output;

            override void Compute()
            {
                streams.Weight = streams.DispatchThreadId.x;
                Output[streams.DispatchThreadId.x] = streams.Weight;
            }
        };
        """;

    const string NewShader = """
        shader {0}
        {
            module float Twice(float x)
            {
                return 2 * x;
            }
        };
        """;

    private readonly string id = Guid.NewGuid().ToString("N");
    private readonly DirectoryInfo sourceDir;
    private readonly FileSystemProvider sourceProvider;

    public ShaderSourceUpgradeTests()
    {
        sourceDir = Directory.CreateDirectory(Path.Combine(AppContext.BaseDirectory, $"upgrade-src-{id}"));
        sourceProvider = new FileSystemProvider($"/upgradetest-{id}", AppContext.BaseDirectory);
    }

    public void Dispose()
    {
        sourceProvider.Dispose();
        sourceDir.Delete(recursive: true);
        GC.SuppressFinalize(this);
    }

    private string Name(string prefix) => $"{prefix}{id}";

    private static string Code(string format, string name, string? parent = null) => format.Replace("{0}", name).Replace("{1}", parent);

    private ShaderSourceManager CreateManager(IVirtualFileProvider fileProvider, params string[] directories)
    {
        var manager = new ShaderSourceManager(fileProvider);
        manager.LookupDirectoryList.AddRange(directories);
        return manager;
    }

    [Fact]
    public void OldSourceIsUpgradedAloneAndOnce()
    {
        var nodeBase = Name("NodeBase");
        var node = Name("Node");
        string? FindClass(string name) => name == nodeBase ? Code(NodeBase, nodeBase) : null;
        var result = ShaderUpgrader.UpgradeSource($"{node}.sdsl", Code(OldComputeNode, node, nodeBase), FindClass);

        Assert.Equal(["stage-to-module", "module-units"], result.ChangedSteps);
        Assert.Contains("module stream float Weight;", result.Text);
        // It overrides a method of its base: it is a node used in compositions, which reads the streams through ComputeShaderStreams
        Assert.Contains($"shader {node} : {nodeBase}\n", result.Text.ReplaceLineEndings("\n"));
        Assert.Contains("import ComputeShaderStreams;", result.Text);

        // Idempotent: the new text is up to date
        var again = ShaderUpgrader.UpgradeSource($"{node}.sdsl", result.Text, FindClass);
        Assert.Empty(again.ChangedSteps);
        Assert.Equal(result.Text, again.Text);
    }

    // A root shader with a helper parent keeps the entry point of ComputeShaderBase
    [Fact]
    public void RootComputeShaderKeepsComputeShaderBase()
    {
        const string text = """
            shader Helpers
            {
                float Twice(float x) { return 2 * x; }
            };

            shader MyCompute : ComputeShaderBase, Helpers
            {
                RWBuffer<float> Output;

                override void Compute()
                {
                    Output[streams.DispatchThreadId.x] = Twice(streams.DispatchThreadId.x);
                }
            };
            """;
        var result = ShaderUpgrader.UpgradeSource("a.sdsl", text);
        Assert.Contains("import ComputeShaderBase;", result.Text);
        Assert.DoesNotContain("ComputeShaderStreams", result.Text);
    }

    // A shader used by name (only a module can be) becomes a parent, as the compiler did before 4.5
    [Fact]
    public void ShaderUsedByNameBecomesAParent()
    {
        const string helper = """
            shader ColorHelpers
            {
                float Twice(float x) { return 2 * x; }
            };
            """;
        const string text = """
            shader MyColor : ComputeColor
            {
                override float4 Compute()
                {
                    return float4(ColorHelpers.Twice(0.25), 0, 0, 1);
                }
            };
            """;
        var result = ShaderUpgrader.UpgradeSource("MyColor.sdsl", text, name => name == "ColorHelpers" ? helper : null);
        Assert.Equal(["module-units"], result.ChangedSteps);
        Assert.Contains("shader MyColor : ComputeColor, ColorHelpers", result.Text);
    }

    // Only a whole project shows that nothing has instances of a class: alone, a helper class stays a shader
    [Fact]
    public void ClassesOfASourceStayShaders()
    {
        const string text = """
            shader Helpers
            {
                float3 Twice(float3 x) { return 2 * x; }
            };

            shader UsesHelpers : Helpers
            {
                float3 Four(float3 x) { return Twice(Twice(x)); }
            };
            """;

        Assert.Contains("module Helpers", ShaderUpgrader.Upgrade(new Dictionary<string, string> { ["a.sdsl"] = text }, EngineShaderClasses.Current).Files["a.sdsl"]);
        var alone = ShaderUpgrader.UpgradeSource("a.sdsl", text);
        Assert.Empty(alone.ChangedSteps);
        Assert.Equal(text, alone.Text);
    }

    [Fact]
    public void AddedSourceIsUpgradedWithAWarning()
    {
        var nodeBase = Name("NodeBase");
        var node = Name("Added");
        var manager = CreateManager(sourceProvider);
        manager.AddShaderSource(nodeBase, Code(NodeBase, nodeBase), $"{nodeBase}.sdsl");
        manager.AddShaderSource(node, Code(OldComputeNode, node, nodeBase), $"{node}.sdsl");

        var source = manager.LoadShaderSource(node);
        Assert.Contains("module stream float Weight;", source.Source);
        Assert.Contains("import ComputeShaderStreams;", source.Source);
        Assert.Equal(ObjectId.FromBytes(Encoding.UTF8.GetBytes(source.Source)), source.Hash);
        var warning = manager.GetUpgradeWarning($"{node}.sdsl");
        Assert.NotNull(warning);
        Assert.StartsWith("SDSL0216:", warning);
        Assert.Contains("stage-to-module, module-units", warning);
        Assert.Contains("imports ComputeShaderStreams instead of ComputeShaderBase", warning);
        Assert.Null(manager.GetUpgradeWarning($"{nodeBase}.sdsl"));

        // A new version written for today replaces it, and its warning
        manager.DeleteObsoleteCache([node]);
        manager.AddShaderSource(node, Code(NewShader, node), $"{node}.sdsl");
        Assert.Equal(Code(NewShader, node), manager.LoadShaderSource(node).Source);
        Assert.Null(manager.GetUpgradeWarning($"{node}.sdsl"));
    }

    [Fact]
    public void FileOnDiskIsUpgraded()
    {
        var nodeBase = Name("FileBase");
        var oldName = Name("OldFile");
        var newName = Name("NewFile");
        File.WriteAllText(Path.Combine(sourceDir.FullName, $"{nodeBase}.sdsl"), Code(NodeBase, nodeBase));
        File.WriteAllText(Path.Combine(sourceDir.FullName, $"{oldName}.sdsl"), Code(OldComputeNode, oldName, nodeBase));
        File.WriteAllText(Path.Combine(sourceDir.FullName, $"{newName}.sdsl"), Code(NewShader, newName));
        var manager = CreateManager(sourceProvider, sourceDir.Name);

        var old = manager.LoadShaderSource(oldName);
        Assert.Contains("module stream float Weight;", old.Source);
        Assert.Contains("import ComputeShaderStreams;", old.Source);
        Assert.NotNull(manager.GetUpgradeWarning(old.Path));

        // Up to date: the text and the hash of the file
        var current = manager.LoadShaderSource(newName);
        Assert.Equal(Code(NewShader, newName), current.Source);
        Assert.Equal(ObjectId.FromBytes(File.ReadAllBytes(Path.Combine(sourceDir.FullName, $"{newName}.sdsl"))), current.Hash);
        Assert.Null(manager.GetUpgradeWarning(current.Path));
    }

    // The asset pipeline imported it: the project upgrade is the one that updates it
    [Fact]
    public void SourceFromTheContentDatabaseIsNotUpgraded()
    {
        var name = Name("Imported");
        using var database = new DatabaseFileProvider(ObjectDatabase.CreateDefaultDatabase());
        using (var stream = database.OpenStream($"upgradetest-{id}/{name}.sdsl", VirtualFileMode.Create, VirtualFileAccess.Write))
            stream.Write(Encoding.UTF8.GetBytes(Code(OldComputeNode, name, "ComputeColor")));
        var manager = CreateManager(database, $"upgradetest-{id}");

        var source = manager.LoadShaderSource(name);
        Assert.Equal(Code(OldComputeNode, name, "ComputeColor"), source.Source);
        Assert.Null(manager.GetUpgradeWarning(source.Path));
    }

    [Fact]
    public void UpgradeCanBeTurnedOff()
    {
        var name = Name("Off");
        var manager = CreateManager(sourceProvider);
        manager.UpgradeSources = false;
        manager.AddShaderSource(name, Code(OldComputeNode, name, "ComputeColor"), $"{name}.sdsl");

        Assert.Equal(Code(OldComputeNode, name, "ComputeColor"), manager.LoadShaderSource(name).Source);
        Assert.Null(manager.GetUpgradeWarning($"{name}.sdsl"));
    }

    // The upgraded node mixes in a composition (it fails without the upgrade), and the effect log has its warning once
    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void UpgradedNodeMixesWithOneWarning(bool upgrade)
    {
        // Names of their own: the compiled classes are kept in the application cache
        var root = Name($"Root{upgrade}");
        var nodeBase = Name($"NodeBase{upgrade}");
        var node = Name($"Node{upgrade}");
        var loader = new FileShaderLoader(sourceProvider) { WarningsAsErrors = false };
        loader.SourceManager.UpgradeSources = upgrade;
        loader.SourceManager.LookupDirectoryList.Add("assets/Stride/SDSL");
        loader.SourceManager.AddShaderSource(nodeBase, Code(NodeBase, nodeBase), $"{nodeBase}.sdsl");
        loader.SourceManager.AddShaderSource(root, $$"""
            shader {{root}}
            {
                import ComputeShaderBase;

                compose {{nodeBase}} Children[];

                override void Compute()
                {
                    foreach (var child in Children)
                        child.Compute();
                }
            };
            """, $"{root}.sdsl");
        loader.SourceManager.AddShaderSource(node, Code(OldComputeNode, node, nodeBase), $"{node}.sdsl");

        var source = new ShaderMixinSource { Mixins = { new ShaderClassSource(root) } };
        source.AddCompositionToArray("Children", new ShaderClassSource(node));
        source.AddCompositionToArray("Children", new ShaderClassSource(node));
        var log = new LoggerResult();
        var mixed = new ShaderMixer(loader).MergeSDSL(source, new ShaderMixer.Options(true), log, out _, out _, out _, out _);
        var messages = string.Join(Environment.NewLine, log.Messages.Select(m => m.Text));
        if (!upgrade)
        {
            // `stage` fails first; with `module` written by hand, SDSL0119 would
            Assert.False(mixed);
            Assert.Contains("SDSL0045", messages);
            return;
        }
        Assert.True(mixed, messages);

        var warnings = log.Messages.Where(m => m.Type == LogMessageType.Warning).Select(m => m.Text).ToList();
        Assert.Single(warnings, x => x.Contains("SDSL0216") && x.Contains($"{node}.sdsl"));
        Assert.DoesNotContain(warnings, x => x.Contains("SDSL0216") && !x.Contains($"{node}.sdsl"));
    }
}
